package events

import (
	"context"
	"testing"

	"github.com/navidrome/navidrome/model/request"
)

func TestMessageDelivery(t *testing.T) {
	b := &broker{}
	sender := request.WithClientUniqueId(request.WithUsername(context.Background(), "alice"), "window-1")
	filtered := b.prepareMessage(sender, &RefreshResource{})
	tests := []struct {
		name string
		msg message
		client client
		want bool
	}{
		{"origin", filtered, client{username: "alice", clientUniqueId: "window-1"}, false},
		{"same user", filtered, client{username: "alice", clientUniqueId: "window-2"}, true},
		{"other user", filtered, client{username: "bob", clientUniqueId: "window-3"}, false},
		{"broadcast", b.prepareMessage(context.Background(), &RefreshResource{}), client{username: "bob", clientUniqueId: "window-3"}, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.msg.shouldDeliver(tt.client); got != tt.want {
				t.Fatalf("shouldDeliver() = %v, want %v", got, tt.want)
			}
		})
	}
}

